function useMutation(refresh:()=>void,supplied?:typeof api){const inherited=useApi(),caller=supplied??inherited;return async<T,>(path:string,body:Record<string,unknown>,method?:string)=>{try{const result=await sendMutation<T>(path,body,method,undefined,caller);refresh();return result;}catch(e){if(e instanceof ApiError&&e.status===409)refresh();throw e;}};}

